# Case-series groups (Freeway Phantom, Silver Dollar Group, ...), derived
# directly from each case's own caseSeries field so this never drifts out
# of sync with the case data itself.
def case_series_groups():
    groups = {}
    for c in CASES:
        s = c.get("caseSeries")
        if s:
            groups.setdefault(s, []).append(c["id"])
    return groups

CONNECTIONS_JSON = json.dumps({
    "links": CASE_CONNECTIONS,
    "series": case_series_groups(),
    "seriesSlugs": SERIES_SLUGS,
}, separators=(",", ":"))

